'use strict';

// MODULES //

var tape = require( 'tape' );
var toAccessorArray = require( '@stdlib/array/base/to-accessor-array' );
var zeros = require( '@stdlib/array/zeros' );
var gconvolutionMatrix = require( './../lib/ndarray.js' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof gconvolutionMatrix, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 10', function test( t ) {
	t.strictEqual( gconvolutionMatrix.length, 10, 'has expected arity' );
	t.end();
});

tape( 'the function returns the output array', function test( t ) {
	var out;
	var v;
	var x;

	x = [ 1.0, 2.0, 3.0 ];
	out = zeros( 15, 'generic' );

	v = gconvolutionMatrix( 'full', 3, 3, x, 1, 0, out, 3, 1, 0 );

	t.strictEqual( v, out, 'returns expected value' );
	t.end();
});

tape( 'the function returns the output array (accessors)', function test( t ) {
	var out;
	var v;
	var x;

	x = toAccessorArray( [ 1.0, 2.0, 3.0 ] );
	out = toAccessorArray( zeros( 15, 'generic' ) );

	v = gconvolutionMatrix( 'full', 3, 3, x, 1, 0, out, 3, 1, 0 );

	t.strictEqual( v, out, 'returns expected value' );
	t.end();
});

tape( 'the function generates a convolution matrix (full, row-major)', function test( t ) {
	var expected;
	var out;
	var x;

	x = [ 1.0, 2.0, 3.0 ];
	out = zeros( 15, 'generic' );

	gconvolutionMatrix( 'full', 3, 3, x, 1, 0, out, 3, 1, 0 );

	expected = [ 1.0, 0.0, 0.0, 2.0, 1.0, 0.0, 3.0, 2.0, 1.0, 0.0, 3.0, 2.0, 0.0, 0.0, 3.0 ];

	t.deepEqual( out, expected, 'returns expected value' );
	t.end();
});

