tape( 'if provided `m` less than or equal to `0`, the function returns the output array unchanged', function test( t ) {
	var expected;
	var out;
	var x;

	x = [ 1.0, 2.0, 3.0 ];
	out = [ 0.0, 0.0, 0.0 ];

	gconvolutionMatrix( 'full', 0, 3, x, 1, 0, out, 3, 1, 0 );

	expected = [ 0.0, 0.0, 0.0 ];

	t.deepEqual( out, expected, 'returns expected value' );

	out = [ 0.0, 0.0, 0.0 ];
	gconvolutionMatrix( 'full', -1, 3, x, 1, 0, out, 3, 1, 0 );

	t.deepEqual( out, expected, 'returns expected value' );
	t.end();
});

